    engine = 'comfyui'
    genre = Genre.OTHER
    label = 'DWPose'
    description = 'DWPose whole-body pose detection (preprocessor for pose-guided generation).'
    form = 'form_edit'
    # card: NONE — a tool lane, not a family head of image-edit
